using namespace std;

#define pb push_back
#define ppb pop_back
#define mp make_pair
#define fs first
#define sc second
#define abs(a) ((a) < 0 ? -(a) : (a))
#define sqr(a) ((a) * (a))

typedef unsigned int uint;
typedef long long ll;
typedef unsigned long long ull;

const double eps = 1e-9;
const int mod = (int)1e+9 + 7;
const double pi = acos(-1.);
const int maxn = 1000100;

int snm[maxn];
int sz[maxn];

int getroot(int u) {
	return(snm[u] == u ? u : (snm[u] = getroot(snm[u])));
}

void merge(int u, int v) {
	u = getroot(u), v = getroot(v);
	if(u != v) {
		sz[u] += sz[v];
		snm[v] = u;
	}
}

int isok(ll a, ll b, ll p) {
	ll res = 1;
	while(b) {
		if(b & 1) {
			res = res * a % p;
		}
		a = a * a % p;
		b >>= 1;
	}
	return(res == 1 ? p : 1);
}

int binpow(ll a, ll b) {
	ll res = 1;
	while(b) {
		if(b & 1) {
			res = res * a % mod;
		}
		a = a * a % mod;
		b >>= 1;
	}
	return(res);
}

int main() {

	#ifdef SOL
