		if(!file.empty()) {
			freopen((file + ".in").c_str(), "r", stdin);
			freopen((file + ".out").c_str(), "w", stdout);
		}
	}
	#endif

	int p, k;
	scanf("%d%d", &p, &k);

	if(k == 0) {
		cout << binpow(p, p - 1);
		return(0);
	}

	for(int i = 0; i < p; i++) {
		snm[i] = i;
		sz[i] = 1;
	}

	for(int i = 0; i < p; i++) {
		merge((k * 1ll * i) % p, i);
	}
	ll ans = 1;
	for(int i = 0; i < p; i++) {
		if(getroot(i) == i) {
			ans = (ans * 1ll * isok(k, sz[i], p)) % mod;
		}
	}

	printf("%lld", ans);

	#ifdef SOL
	{
